<?php
require __DIR__.'/banco_brasil_api_monthly_interest.php';
use BancoBrasil\ApiFixedDiscount;
apiCheck(ApiFixedDiscount::declaration([])===[]&&ApiFixedDiscount::declaration(['discount_policy'=>'none'])===[],'legacy/no-discount definitions remain byte compatible');
apiReject(fn()=>ApiFixedDiscount::declaration(['discount_policy'=>'fixed_until']),'bb_api_discount_contract_required');
$discount=ApiFixedDiscount::declaration(['discount_policy'=>'fixed_until','discount_policy_confirmed'=>'1']);$invoice=['date'=>'2026-10-19','duedate'=>'2026-11-19'];
apiCheck(ApiFixedDiscount::parameters($discount,['fixed_discount'=>'10.0','discount_until'=>'2026-10-29'],$invoice,'2026-10-19',10000)===['tipo'=>1,'dataExpiracao'=>'29.10.2026','valor'=>'10.00'],'fixed first discount is exact money/date, not a percentage or a financial reduction');
foreach(['0','-1','1.001','1e2',' 1','01.00',1.0] as $invalid)apiReject(fn()=>ApiFixedDiscount::amount($invalid),'bb_api_discount_invalid');
foreach(['2026-02-30','29.10.2026',null] as $invalid)apiReject(fn()=>ApiFixedDiscount::date($invalid),'bb_api_discount_invalid');
apiReject(fn()=>ApiFixedDiscount::parameters([],['fixed_discount'=>'10.00','discount_until'=>'2026-10-29'],$invoice,'2026-10-19',10000),'bb_api_discount_profile_denied');
apiReject(fn()=>ApiFixedDiscount::parameters($discount,['fixed_discount'=>'100.00','discount_until'=>'2026-10-29'],$invoice,'2026-10-19',10000),'bb_api_discount_exceeds_nominal');
foreach(['2026-10-18','2026-11-20'] as $invalid)apiReject(fn()=>ApiFixedDiscount::parameters($discount,['fixed_discount'=>'10.00','discount_until'=>$invalid],$invoice,'2026-10-19',10000),'bb_api_discount_date_requires_review');
$data=['desconto'=>['tipo'=>1,'dataExpiracao'=>'29.10.2026','valor'=>'10.00'],'jurosMora'=>['tipo'=>2,'porcentagem'=>'1.25'],'other'=>'10.00'];$wire=ApiFixedDiscount::encode(BancoBrasil\ApiDailyInterest::encode($data),$data);apiCheck($wire==='{"desconto":{"tipo":1,"dataExpiracao":"29.10.2026","valor":10.00},"jurosMora":{"tipo":2,"porcentagem":1.25},"other":"10.00"}','discount and optional monthly rate retain exact JSON numbers without coercing unrelated strings');$payload=BancoBrasil\ApiClient::decodeExact($wire);
$detail=['codigoDescontoTitulo'=>'1','valorDescontoTitulo'=>'10.00','percentualDescontoTitulo'=>'0','dataDescontoTitulo'=>'29.10.2026','codigoSegundoDescontoTitulo'=>'0','valorSegundoDescontoTitulo'=>'0','percentualSegundoDescontoTitulo'=>'0','codigoTerceiroDescontoTitulo'=>'0','valorTerceiroDescontoTitulo'=>'0','percentualTerceiroDescontoTitulo'=>'0'];ApiFixedDiscount::confirm($detail,$payload);apiCheck(true,'query confirms first offer and explicitly excludes other discounts');foreach([['codigoDescontoTitulo'=>'2'],['valorDescontoTitulo'=>'10.01'],['percentualDescontoTitulo'=>'1'],['dataDescontoTitulo'=>'30.10.2026'],['codigoSegundoDescontoTitulo'=>'1'],['valorTerceiroDescontoTitulo'=>'1']] as $change)apiReject(fn()=>ApiFixedDiscount::confirm(array_replace($detail,$change),$payload),'bb_api_discount_query_mismatch');$missing=$detail;unset($missing['codigoSegundoDescontoTitulo']);apiReject(fn()=>ApiFixedDiscount::confirm($missing,$payload),'bb_api_discount_query_mismatch');
echo 'BB fixed first discount: '.$n.' cumulative contract checks; no financial application or bank operations.'.PHP_EOL;
